// Open-source licences (v1.1, RELEASE_KIT 1c item 15): every package in the release JS bundles and every linked native
// package with its licence text (generated by scripts/gen-licences.mjs), plus the native parts React Native builds in.
import { useState } from 'react';
import { FlatList, Pressable, StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Spacing } from '@/constants/theme';
import { useTheme } from '@/hooks/use-theme';
import { t } from '@/i18n';
import { LICENCES, LICENCE_TEXTS, NATIVE_COMPONENTS } from '@/lib/licences.generated';

export default function LicencesScreen() {
  const theme = useTheme();
  const [open, setOpen] = useState<string | null>(null);
  return (
    <FlatList
      testID="licences-screen"
      style={{ backgroundColor: theme.background }}
      contentContainerStyle={styles.content}
      contentInsetAdjustmentBehavior="automatic"
      data={LICENCES}
      keyExtractor={(r) => r[0]}
      ListHeaderComponent={
        <ThemedText type="small" themeColor="textSecondary">
          {t('licences.intro', { n: LICENCES.length })}
        </ThemedText>
      }
      renderItem={({ item: [name, version, id, ti] }) => (
        <View style={[styles.card, { backgroundColor: theme.backgroundElement }]}>
          <Pressable testID={`licence-${name}`} accessibilityRole="button" onPress={() => setOpen(open === name ? null : name)}>
            <ThemedText type="smallBold">{`${name} ${version}`}</ThemedText>
            <ThemedText type="small" themeColor="textSecondary">
              {`${id} · ${open === name ? t('licences.hide') : t('licences.show')}`}
            </ThemedText>
          </Pressable>
          {open === name && ti >= 0 ? <ThemedText style={styles.text}>{LICENCE_TEXTS[ti]}</ThemedText> : null}
        </View>
      )}
      ListFooterComponent={
        <View style={[styles.card, { backgroundColor: theme.backgroundElement }]}>
          <ThemedText type="smallBold">{t('licences.native')}</ThemedText>
          {NATIVE_COMPONENTS.map(([what, id]) => (
            <ThemedText key={what} type="small">{`${what} — ${id}`}</ThemedText>
          ))}
        </View>
      }
    />
  );
}

const styles = StyleSheet.create({
  content: { padding: Spacing.three, gap: Spacing.two, paddingBottom: 64 },
  card: { padding: Spacing.three, borderRadius: 12, gap: Spacing.one },
  text: { fontSize: 11, lineHeight: 15 },
});
